func sendFrameEvent(ctx context.Context, out chan<- backend.FrameEvent, ev backend.FrameEvent, timeout time.Duration) bool {
	if timeout <= 0 {
		select {
		case out <- ev:
			return true
		case <-ctx.Done():
			return false
		}
	}
	timer := time.NewTimer(timeout)
	defer timer.Stop()
	select {
	case out <- ev:
		return true
	case <-timer.C:
		return false
	case <-ctx.Done():
		return false
	}
}

